//! Black-box regression suite for bzip2: `.bz2` files, `.tar.bz2`, ZIP
//! method 12 and bzip2-compressed UDIF disk images.
//!
//! Every fixture is an embedded byte array produced once by python3
//! (`bz2`, `tarfile`, `zipfile`), hfsutils and `hdiutil`; nothing here needs
//! external tools. Expected contents are regenerated by the helpers below.
#![cfg(feature = "full")]

use std::io::{Cursor, Write};

use unretro::{ContainerFormat, EntryType, Loader, VisitAction, detect_format};

type Listing = Vec<(String, Vec<u8>)>;

/// Leaves at any depth, sorted by path. Any traversal diagnostic is an error.
fn leaves(data: &[u8], name: &str) -> Result<Listing, String> {
    let mut entries = Listing::new();
    let report = Loader::from_bytes(data.to_vec(), name)
        .visit_with_report(EntryType::Leaves, |entry| {
            entries.push((entry.path.to_string(), entry.data.to_vec()));
            Ok(VisitAction::Continue)
        })
        .map_err(|e| e.to_string())?;
    if let Some(diagnostic) = report.diagnostics.first() {
        return Err(diagnostic.message.clone());
    }
    entries.sort();
    Ok(entries)
}

#[track_caller]
fn assert_leaves(data: &[u8], name: &str, expected: &[(&str, &[u8])]) {
    let listing = leaves(data, name).unwrap_or_else(|e| panic!("{name} rejected: {e}"));
    let mut expected: Vec<(&str, &[u8])> = expected.to_vec();
    expected.sort();
    let got: Vec<&str> = listing.iter().map(|(path, _)| path.as_str()).collect();
    let want: Vec<&str> = expected.iter().map(|(path, _)| *path).collect();
    assert_eq!(got, want, "entry paths of {name}");
    for ((path, data), (_, want)) in listing.iter().zip(&expected) {
        assert_eq!(data.len(), want.len(), "size of {path}");
        assert!(data == want, "content of {path} differs");
    }
}

#[track_caller]
fn assert_rejected(data: &[u8], name: &str) {
    if let Ok(listing) = leaves(data, name) {
        let paths: Vec<&str> = listing.iter().map(|(path, _)| path.as_str()).collect();
        panic!("corrupt {name} was accepted: {paths:?}");
    }
}

const TEXT: &[u8] = b"It was the best of times, it was the worst of times, it was the age of wisdom, it was the age of foolishness, it was the epoch of belief, it was the epoch of incredulity.\n";
const SECOND: &[u8] = b"second stream\n";

/// Runs around the lengths where bzip2's initial run-length coding changes
/// shape (4, 255 + 4) for the bytes 0x00, 'A' and 0xFF.
fn runs() -> Vec<u8> {
    let mut out = Vec::new();
    for len in [
        1, 2, 3, 4, 5, 6, 254, 255, 256, 257, 258, 259, 260, 261, 515, 1000,
    ] {
        for byte in [0x00, b'A', 0xFF] {
            out.resize(out.len() + len, byte);
            out.push(b'|');
        }
    }
    out
}

/// Compressible data that spans three blocks at level 1.
fn pattern() -> Vec<u8> {
    (0..250_000u64).map(|i| ((i * i) % 31) as u8).collect()
}

fn long_name() -> String {
    format!("dir/{}.txt", "n".repeat(120))
}

