#[test]
fn bz2_file_yields_one_entry_named_after_the_file() {
    assert_leaves(BZ_TEXT, "t.txt.bz2", &[("t.txt.bz2/t.txt", TEXT)]);
    assert_leaves(BZ_TEXT, "T.TXT.BZ2", &[("T.TXT.BZ2/T.TXT", TEXT)]);
    assert_leaves(BZ_TEXT, "t.bzip2", &[("t.bzip2/t", TEXT)]);
    assert_leaves(BZ_EMPTY, "e.bin.bz2", &[("e.bin.bz2/e.bin", b"")]);

    let info = Loader::from_bytes(BZ_TEXT.to_vec(), "t.txt.bz2")
        .info()
        .unwrap();
    assert_eq!(info.format, ContainerFormat::Bzip2);
}

#[test]
fn bz2_run_lengths_and_multiple_blocks_decode_exactly() {
    assert_leaves(BZ_RUNS, "r.bin.bz2", &[("r.bin.bz2/r.bin", &runs())]);
    let pattern = pattern();
    assert_leaves(BZ_PATTERN_L1, "p.bin.bz2", &[("p.bin.bz2/p.bin", &pattern)]);
    assert_leaves(BZ_PATTERN_L9, "p.bin.bz2", &[("p.bin.bz2/p.bin", &pattern)]);

    // Blocks may be smaller than the header's block size, never larger.
    let mut roomy = BZ_PATTERN_L1.to_vec();
    roomy[3] = b'9';
    assert_leaves(&roomy, "p.bin.bz2", &[("p.bin.bz2/p.bin", &pattern)]);
    let mut cramped = BZ_PATTERN_L9.to_vec();
    cramped[3] = b'1';
    assert_rejected(&cramped, "p.bin.bz2");
}

#[test]
fn concatenated_streams_decode_as_one_file() {
    let both = [TEXT, SECOND].concat();
    let streams = [BZ_TEXT, BZ_SECOND].concat();
    assert_leaves(&streams, "m.txt.bz2", &[("m.txt.bz2/m.txt", &both)]);

    // Empty streams contribute nothing, wherever they sit.
    let padded = [BZ_EMPTY, BZ_TEXT, BZ_EMPTY, BZ_EMPTY, BZ_SECOND, BZ_EMPTY].concat();
    assert_leaves(&padded, "m.txt.bz2", &[("m.txt.bz2/m.txt", &both)]);

    let pattern = pattern();
    let expected = [&pattern[..], TEXT, &pattern[..]].concat();
    let mixed = [BZ_PATTERN_L1, BZ_TEXT, BZ_PATTERN_L9].concat();
    assert_leaves(&mixed, "m.bz2", &[("m.bz2/m", &expected)]);
}

#[test]
fn trailing_bytes_after_the_last_stream_are_ignored() {
    for garbage in [
        &[0u8; 700][..],
        b"\n",
        b"BZ",
        b"BZh",
        b"BZh0",
        b"trailing garbage",
        b"\xff\xfe\xfd",
    ] {
        let padded = [BZ_TEXT, garbage].concat();
        assert_leaves(&padded, "t.txt.bz2", &[("t.txt.bz2/t.txt", TEXT)]);
    }
}

#[test]
fn bzip2_is_detected_by_content_whatever_the_name() {
    for name in ["noext", "wrong.gz", "wrong.zip", "wrong.txt", "wrong.dat"] {
        assert_eq!(
            detect_format(name, Some(BZ_TEXT)),
            Some(ContainerFormat::Bzip2),
            "{name}"
        );
        let listing = leaves(BZ_TEXT, name).unwrap();
        assert_eq!(listing.len(), 1, "{name}");
        assert!(listing[0].0.starts_with(&format!("{name}/")), "{name}");
        assert!(listing[0].1 == TEXT, "{name}");
    }
    assert_eq!(
        detect_format("e", Some(BZ_EMPTY)),
        Some(ContainerFormat::Bzip2)
    );

    // The extension alone is not enough.
    for data in [&b"BZh9 is not a stream"[..], b"BZh", b"", &BZ_TEXT[1..]] {
        assert_ne!(
            detect_format("t.bz2", Some(data)),
            Some(ContainerFormat::Bzip2)
        );
    }
}

fn tar_listing(root: &str) -> Vec<(String, Vec<u8>)> {
    vec![
        (format!("{root}/hello.txt"), b"hello\n".to_vec()),
        (format!("{root}/{}", long_name()), b"long name\n".to_vec()),
        (format!("{root}/dir/text.txt"), TEXT.to_vec()),
        (format!("{root}/empty"), Vec::new()),
    ]
}

#[track_caller]
fn assert_tar(data: &[u8], name: &str, root: &str) {
    let expected = tar_listing(root);
    let expected: Vec<(&str, &[u8])> = expected
        .iter()
        .map(|(path, data)| (path.as_str(), data.as_slice()))
        .collect();
    assert_leaves(data, name, &expected);
}

#[test]
fn tar_bz2_lists_the_files_of_the_inner_tar() {
    assert_tar(TAR_BZ2, "a.tar.bz2", "a.tar.bz2/a.tar");
    for name in ["a.tbz2", "a.tbz", "a.tb2", "A.TBZ2"] {
        let stem = &name[..1];
        assert_tar(TAR_BZ2, name, &format!("{name}/{stem}.tar"));
    }
    // Without any hint in the name the payload is still recognized as TAR.
    assert_tar(TAR_BZ2, "archive", "archive/archive");

    // The tar may be cut into separately compressed streams at any point.
    let split = [TAR_BZ2, BZ_EMPTY].concat();
    assert_tar(&split, "a.tar.bz2", "a.tar.bz2/a.tar");
}

#[test]
fn bz2_nested_in_zip_and_tar_is_opened() {
    let mut zip = zip::ZipWriter::new(Cursor::new(Vec::new()));
    let stored =
        zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Stored);
    zip.start_file("inner.txt.bz2", stored).unwrap();
    zip.write_all(BZ_TEXT).unwrap();
    zip.start_file("sub/a.tbz2", stored).unwrap();
    zip.write_all(TAR_BZ2).unwrap();
    let zip = zip.finish().unwrap().into_inner();
    let mut expected = tar_listing("n.zip/sub/a.tbz2/a.tar");
    expected.push(("n.zip/inner.txt.bz2/inner.txt".to_string(), TEXT.to_vec()));
    let expected: Vec<(&str, &[u8])> = expected
        .iter()
        .map(|(path, data)| (path.as_str(), data.as_slice()))
        .collect();
    assert_leaves(&zip, "n.zip", &expected);

    let mut tar = tar::Builder::new(Vec::new());
    for (name, data) in [("inner.txt.bz2", BZ_TEXT), ("sub/a.tar.bz2", TAR_BZ2)] {
        let mut header = tar::Header::new_gnu();
        header.set_size(data.len() as u64);
        header.set_mode(0o644);
        tar.append_data(&mut header, name, data).unwrap();
    }
    let tar = tar.into_inner().unwrap();
    let mut expected = tar_listing("n.tar/sub/a.tar.bz2/a.tar");
    expected.push(("n.tar/inner.txt.bz2/inner.txt".to_string(), TEXT.to_vec()));
    let expected: Vec<(&str, &[u8])> = expected
        .iter()
        .map(|(path, data)| (path.as_str(), data.as_slice()))
        .collect();
    assert_leaves(&tar, "n.tar", &expected);

    // bzip2 inside bzip2.
    assert!(leaves(BZ_BZ_TEXT, "t.txt.bz2.bz2").unwrap()[0].1 == TEXT);
}

#[test]
fn zip_method_12_entries_are_extracted_next_to_stored_and_deflated_ones() {
    let doubled = [TEXT, TEXT].concat();
    assert_leaves(
        ZIP_BZIP2,
        "t.zip",
        &[
            ("t.zip/text.txt", TEXT),
            ("t.zip/stored.txt", b"stored\n"),
            ("t.zip/dir/deflated.txt", &doubled),
            ("t.zip/dir/runs.bin", &runs()),
            ("t.zip/empty.bin", b""),
        ],
    );
}

// Offsets into ZIP_BZIP2: local headers, then central directory records.
const ZIP_LOCAL_TEXT: usize = 0;
const ZIP_LOCAL_RUNS: usize = 349;
const ZIP_CENTRAL_TEXT: usize = 571;
const ZIP_CENTRAL_RUNS: usize = 743;

/// `ZIP_BZIP2` with the 32-bit field at `offset` in the local header and the
/// matching field of the central record of the same entry set to `value`.
fn zip_with_field(local: usize, central: usize, offset: usize, value: u32) -> Vec<u8> {
    let mut zip = ZIP_BZIP2.to_vec();
    assert_eq!(&zip[local..local + 4], b"PK\x03\x04");
    assert_eq!(&zip[central..central + 4], b"PK\x01\x02");
    zip[local + offset..local + offset + 4].copy_from_slice(&value.to_le_bytes());
    // Central records carry two more bytes (version made by) before the same fields.
    zip[central + offset + 2..central + offset + 6].copy_from_slice(&value.to_le_bytes());
    zip
}

/// Paths of `ZIP_BZIP2` entries that still come out with their full content.
fn intact_zip_entries(zip: &[u8]) -> Vec<String> {
    let doubled = [TEXT, TEXT].concat();
    let runs = runs();
    let expected: [(&str, &[u8]); 5] = [
        ("t.zip/text.txt", TEXT),
        ("t.zip/stored.txt", b"stored\n"),
        ("t.zip/dir/deflated.txt", &doubled),
        ("t.zip/dir/runs.bin", &runs),
        ("t.zip/empty.bin", b""),
    ];
    let mut intact = Vec::new();
    let _ =
        Loader::from_bytes(zip.to_vec(), "t.zip").visit_with_report(EntryType::Leaves, |entry| {
            let known = expected.iter().find(|(path, _)| *path == entry.path);
            let Some((path, data)) = known else {
                panic!("unexpected entry {}", entry.path);
            };
            assert!(entry.data == *data, "{path} delivered with wrong content");
            intact.push((*path).to_string());
            Ok(VisitAction::Continue)
        });
    intact
}

#[test]
fn corrupt_zip_method_12_entries_are_rejected_not_delivered() {
    const CRC: usize = 14;
    const COMPRESSED_SIZE: usize = 18;
    const SIZE: usize = 22;
    let text = "t.zip/text.txt".to_string();
    let runs_path = "t.zip/dir/runs.bin".to_string();
    assert_eq!(intact_zip_entries(ZIP_BZIP2).len(), 5);

    // A payload bit flip in each bzip2 entry.
    for (local, path) in [(ZIP_LOCAL_TEXT, &text), (ZIP_LOCAL_RUNS, &runs_path)] {
        let name_len = usize::from(ZIP_BZIP2[local + 26]);
        let mut zip = ZIP_BZIP2.to_vec();
        zip[local + 30 + name_len + 40] ^= 0x10;
        assert_rejected(&zip, "t.zip");
        assert!(!intact_zip_entries(&zip).contains(path));
    }

    let text_len = TEXT.len() as u32;
    let runs_len = runs().len() as u32;
    let cases = [
        (ZIP_LOCAL_TEXT, ZIP_CENTRAL_TEXT, CRC, 0xDEAD_BEEF, &text),
        (ZIP_LOCAL_TEXT, ZIP_CENTRAL_TEXT, SIZE, text_len - 1, &text),
        (ZIP_LOCAL_TEXT, ZIP_CENTRAL_TEXT, SIZE, text_len + 1, &text),
        (ZIP_LOCAL_TEXT, ZIP_CENTRAL_TEXT, SIZE, 0, &text),
        (ZIP_LOCAL_TEXT, ZIP_CENTRAL_TEXT, SIZE, 0x7FFF_FFFF, &text),
        (ZIP_LOCAL_TEXT, ZIP_CENTRAL_TEXT, SIZE, 0xFFFF_FFFE, &text),
        (ZIP_LOCAL_TEXT, ZIP_CENTRAL_TEXT, COMPRESSED_SIZE, 20, &text),
        (
            ZIP_LOCAL_TEXT,
            ZIP_CENTRAL_TEXT,
            COMPRESSED_SIZE,
            0x7FFF_FFFF,
            &text,
        ),
        (
            ZIP_LOCAL_RUNS,
            ZIP_CENTRAL_RUNS,
            SIZE,
            runs_len + 1,
            &runs_path,
        ),
        (
            ZIP_LOCAL_RUNS,
            ZIP_CENTRAL_RUNS,
            SIZE,
            runs_len - 1,
            &runs_path,
        ),
    ];
    for (local, central, field, value, path) in cases {
        let zip = zip_with_field(local, central, field, value);
        assert_rejected(&zip, "t.zip");
        assert!(
            !intact_zip_entries(&zip).contains(path),
            "field {field} = {value:#x} of {path}"
        );
    }
}

#[test]
fn every_truncation_of_a_bz2_file_is_rejected() {
    for file in [BZ_TEXT, BZ_SECOND, BZ_EMPTY, TAR_BZ2] {
        for cut in 0..file.len() {
            assert_rejected(&file[..cut], "t.bz2");
        }
    }
}

#[test]
fn single_bit_damage_never_changes_the_output() {
    // A flipped bit is either caught (block or stream CRC, structure) or
    // lands where it cannot change the decoded bytes; wrong data never
    // comes out.
    let mut rejected = 0;
    for (file, plain) in [(BZ_TEXT, TEXT), (BZ_SECOND, SECOND)] {
        for bit in 0..file.len() * 8 {
            let mut damaged = file.to_vec();
            damaged[bit / 8] ^= 0x80 >> (bit % 8);
            match leaves(&damaged, "t.bz2") {
                Ok(listing) => {
                    assert_eq!(listing.len(), 1, "bit {bit}");
                    assert!(listing[0].1 == plain, "bit {bit} changed the output");
                }
                Err(_) => rejected += 1,
            }
        }
    }
    assert!(
        rejected > (BZ_TEXT.len() + BZ_SECOND.len()) * 7,
        "{rejected}"
    );
}

#[test]
fn damage_in_a_later_stream_or_block_rejects_the_whole_file() {
    let mut streams = [BZ_TEXT, BZ_SECOND].concat();
    let last = streams.len() - 6;
    streams[last] ^= 0x01;
    assert_rejected(&streams, "m.txt.bz2");

    // Third block of BZ_PATTERN_L1.
    let mut blocks = BZ_PATTERN_L1.to_vec();
    let late = blocks.len() - 40;
    blocks[late] ^= 0x20;
    assert_rejected(&blocks, "p.bin.bz2");

    // Stream CRC.
    let mut crc = BZ_PATTERN_L1.to_vec();
    let end = crc.len() - 3;
    crc[end] ^= 0xFF;
    assert_rejected(&crc, "p.bin.bz2");

    let mut tar = TAR_BZ2.to_vec();
    tar[TAR_BZ2.len() / 2] ^= 0x04;
    assert_rejected(&tar, "a.tar.bz2");
}

fn udbz_image() -> Vec<u8> {
    [UDBZ_DATA, UDBZ_PLIST, UDBZ_KOLY].concat()
}

/// The image with 512 zero bytes in front of the data fork, block table and
/// koly trailer adjusted, so that the file no longer starts with `BZh`.
fn udbz_image_with_leading_gap() -> Vec<u8> {
    const GAP: usize = 512;
    let mut plist = UDBZ_PLIST.to_vec();
    // The first <data> is the mish block table. Its 64-bit data offset is
    // bytes 24..32; byte 30 (worth 256) starts the base64 group at 40.
    let open = plist.windows(6).position(|w| w == b"<data>").unwrap() + 6;
    let base64 = open
        + plist[open..]
            .iter()
            .position(|b| !b.is_ascii_whitespace())
            .unwrap();
    assert_eq!(&plist[base64..base64 + 6], b"bWlzaA", "mish signature");
    assert_eq!(&plist[base64 + 40..base64 + 44], b"AAAA", "data offset 0");
    plist[base64 + 40..base64 + 44].copy_from_slice(b"AgAA");

    let mut koly = UDBZ_KOLY.to_vec();
    let xml_offset = (GAP + UDBZ_DATA.len()) as u64;
    koly[216..224].copy_from_slice(&xml_offset.to_be_bytes());

    [&[0u8; GAP][..], UDBZ_DATA, &plist, &koly].concat()
}

fn udbz_bytes_bin() -> Vec<u8> {
    (0..512).map(|i| i as u8).collect()
}

const UDBZ_HELLO: &[u8] = b"hello from a bzip2-compressed disk image\n";

#[test]
fn udbz_disk_image_blocks_are_decoded() {
    let image = udbz_image_with_leading_gap();
    assert_eq!(
        detect_format("v.dmg", Some(&image)),
        Some(ContainerFormat::Hfs)
    );
    assert_leaves(
        &image,
        "v.dmg",
        &[
            ("v.dmg/hello.txt", UDBZ_HELLO),
            ("v.dmg/Folder/bytes.bin", &udbz_bytes_bin()),
        ],
    );
}

#[test]
fn damaged_udbz_blocks_are_rejected() {
    let image = udbz_image_with_leading_gap();
    for offset in [512 + 4, 512 + 100, 512 + UDBZ_DATA.len() / 2] {
        let mut damaged = image.clone();
        damaged[offset] ^= 0x08;
        assert_rejected(&damaged, "v.dmg");
    }
}

// An unmodified `hdiutil` UDBZ image starts with its first bzip2 chunk, so the
// koly trailer has to win over the `.bz2` probe.
#[test]
fn udbz_disk_image_from_hdiutil_opens_as_a_disk_image() {
    let image = udbz_image();
    assert_eq!(
        detect_format("v.dmg", Some(&image)),
        Some(ContainerFormat::Hfs)
    );
    assert_leaves(
        &image,
        "v.dmg",
        &[
            ("v.dmg/hello.txt", UDBZ_HELLO),
            ("v.dmg/Folder/bytes.bin", &udbz_bytes_bin()),
        ],
    );
}
